    (@voyage_id, '1844-03-24 00:00:00', 'Atlantic Ocean (gale/damage/oil leak)', 33.517, -68.217, 'sailing in severe gale; damage; oil leak', 'hard gales; heavy thunder squall', 'SW, then W', 'NNW', JSON_ARRAY(), JSON_OBJECT(), 'Heavy thunder squall split the foresail and main topsail. Oil got adrift between decks and started to leak. Laying too under close reeft main topsail.', 0, 0),
